-- PT108-S2-Q12
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT108-S2-Q12$batch01$ AND q.stimulus=$batch01$Undoubtedly, one's freedom is always worth the risk of losing one's life. Consider a person who is locked in a bare cement room with no hope of escape. This person is not really living and has nothing to lose.$batch01$ AND q.prompt=$batch01$A flaw in the argument's reasoning is that the argument$batch01$ AND q.correct_choice=$batch01$C$batch01$) THEN RAISE EXCEPTION 'Question changed: PT108-S2-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT108-S2-Q12$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT108-S2-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT108-S2-Q12$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$presumes, without providing justification, that nothing can have greater value than one's own freedom$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT108-S2-Q12 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT108-S2-Q12$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$fails to consider that it is not always possible to rebel physically against an encroachment on one's freedom$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT108-S2-Q12 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT108-S2-Q12$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$generalizes inappropriately from a single extreme case to a universal claim$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT108-S2-Q12 C'; END IF; END $guard$;
