DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT108-S2-Q12$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$overlooks the possibility that some people do not have the courage to take risks for freedom$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT108-S2-Q12 E'; END IF; END $guard$;
