INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT108-S2-Q12$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$Freedom is *always* worth risking one's life for.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$A person locked in a bare cement room with no hope of escape is not really living and has nothing to lose.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$That is an extreme deprivation of freedom. Even if risking death is worthwhile in that case, does it follow for every restriction of freedom? A person facing a minor restriction may have a rich life and a great deal to lose. The single case does not support “always.”$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the unjustified move from one extreme example to a universal claim.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT108-S2-Q12$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The author need not think freedom is the most valuable thing in every comparison. The narrower error is treating one exceptionally severe loss of freedom as proof about *every* risk to freedom.$batch01$), ($batch01$B$batch01$, $batch01$Whether physical rebellion is possible does not address the value judgment that taking a life risk is always worthwhile.$batch01$), ($batch01$C$batch01$, $batch01$The bare room is one extreme case. It might justify a life risk for that person without justifying a life risk whenever *anyone's* freedom is at stake. “Always” outruns the example.$batch01$), ($batch01$D$batch01$, $batch01$The conclusion concerns one's *own* freedom. The value of risking one's life for others' freedom is outside its scope.$batch01$), ($batch01$E$batch01$, $batch01$Whether people dare take a risk does not tell us whether the risk is worth taking. Someone can lack courage for a worthwhile action, or take a brave but unwise risk.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT108-S2-Q12$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
